const R=RegimentGame,$=id=>document.getElementById(id),KEY='council-regiments-v0.10';
let state,active=0,selected=0,camera={x:0,y:0,w:1200,h:700},pending=null,unreadableSave=null;
const shields=new Map(),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(items,value)=>items.map(([id,text])=>`<option value="${id}" ${String(id)===String(value)?'selected':''}>${esc(text)}</option>`).join('');
function fresh(){return R.create(generateStudentWorld(crypto.getRandomValues(new Uint32Array(1))[0],GRIA_TEMPLATE));}
function notice(s){$('notice').textContent=s;}
function save(){if(unreadableSave!==null){notice('Autosave paused to protect your unreadable save. Download it, then explicitly open a game or start a new world.');return;}try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notice('Browser storage is full. Download your game before closing.');}}
function change(fn,message){try{const next=structuredClone(state);fn(next);state=R.validate(next);save();render();if(message)notice(message);}catch(e){notice(e.message);}}
function ask(text,fn){pending=fn;$('confirmText').textContent=text;$('confirm').showModal();}
$('cancel').onclick=()=>$('confirm').close();$('confirmYes').onclick=()=>{$('confirm').close();const fn=pending;pending=null;fn?.();};
try{const raw=localStorage.getItem(KEY);state=raw?R.validate(JSON.parse(raw)):fresh();}catch{unreadableSave=localStorage.getItem(KEY);state=fresh();$('recover').hidden=false;notice('Could not open the saved regiment game. Autosave is paused. Download the unreadable save, then open a backup or start a new world.');}
const living=()=>state.units.filter(u=>u.hp>0),country=id=>state.countries[id]?.name||'Unclaimed';
function phaseInfo(){return {orders:['1 · Plan movement','Choose destinations and move or capture. Recruit whole regiments. Everyone’s orders stay pending until the teacher advances.','Teacher: move everyone →'],decisions:['2 · Agreements & targets','Movement is complete. Offer and accept alliances now. For every contested territory, each country chooses one opponent or hold, then confirms.','Teacher: resolve combat →'],retreat:['3 · Retreat','The weaker damaged forces must move one neighboring territory. No safe destination means surrender. Damage remains.','Teacher: finish retreats →'],results:['4 · Results','Review captures, income and battle losses. Download pictures; create your own tables and explanations.','Teacher: start next turn →']}[state.phase];}
function render(){const [title,help,button]=phaseInfo();$('turn').textContent=`TURN ${state.turn}`;$('phase').textContent=title;$('phaseHelp').textContent=help;$('advance').textContent=button;$('country').innerHTML=options(state.countries.map(c=>[c.id,c.name]),active);$('territory').innerHTML=options(state.territories.map(t=>[t.id,`${t.id+1} · ${t.name} · ${country(t.owner)}`]),selected);const c=state.countries[active];$('stocks').innerHTML=R.goods.map(g=>`<span><strong>${Math.floor(c.stock[g])}</strong> ${g}</span>`).join('')+`<span class="badge">Movement ${c.movement}</span>`;
 const t=state.territories[selected];$('territoryInfo').innerHTML=`<strong>${esc(t.name)} · ${esc(country(t.owner))}</strong><p>${esc(t.biome.name)} · ${t.cells.length} small cells grouped · ${t.rough?'Rough ground: −15% attack when crossed':'Easy ground'}<br>Income: 8 money + 4 food + 8 ${t.resource} each turn for its controller.</p>`;
 $('territoryInfo').append(Object.assign(document.createElement('p'),{textContent:'Regiments here: '+(living().filter(u=>u.territory===selected).map(u=>`${country(u.country)} · ${R.types[u.type].name} #${u.id} · ${u.hp} health`).join('; ')||'None')}));
 $('legend').innerHTML=state.phase==='orders'?'<span>♜ Spears → ♞ Cavalry → ➶ Archers → ♜ Spears · ◉ Artillery: neutral against all</span>':'';if($('layer').value==='biome')$('legend').innerHTML+=[...new Map(state.territories.map(t=>[t.biome.i,t.biome])).values()].map(b=>`<span><i class="swatch" style="background:${/^#[\da-f]{6}$/i.test(b.color)?b.color:'#aaa'}"></i>${esc(b.name)}</span>`).join('');
 renderDecisions();renderReport();draw();}
function renderDecisions(){const panel=$('decisions');$('decisionTitle').textContent=state.phase==='orders'?'One order per regiment':state.phase==='decisions'?'Agree, then choose your opponent':state.phase==='retreat'?'Choose safe retreats':'Your turn is complete';panel.replaceChildren();
 if(state.phase==='orders'){
  const c=state.countries[active],owned=state.territories.filter(t=>t.owner===active),section=document.createElement('div');section.innerHTML=`<div class="row"><label>Recruit <select id="recruitType">${options(Object.entries(R.types).map(([k,t])=>[k,t.name]),'spears')}</select></label><label>At <select id="recruitAt">${options(owned.map(t=>[t.id,`${t.id+1} · ${t.name}`]),owned[0]?.id)}</select></label><button id="recruit">Recruit a 100-health unit</button></div><p>50 money + 20 food + 20 metal / 5 wood (spears, cavalry or artillery), or 20 wood / 5 metal (archers). Maximum six living units. Artillery has neutral field matchups; its city-capture bonus will arrive with cities.</p><button id="research" ${c.research||c.movement>=4?'disabled':''}>${c.research?'Movement research funded':c.movement>=4?'Movement fully researched':'Research +1 movement · 60 money, 15 wood, 15 metal'}</button>`;panel.append(section);$('recruit').onclick=()=>change(s=>R.recruit(s,active,$('recruitType').value,Number($('recruitAt').value)),'Regiment recruited.');$('research').onclick=()=>change(s=>R.research(s,active),'Research funded. Extra movement begins next turn.');
  living().filter(u=>u.country===active).forEach(u=>{const destinations=state.territories.filter(t=>{const p=R.route(state,u.territory,t.id,u.country);return p&&p.length<=c.movement;});const box=document.createElement('article');box.className='regiment';box.innerHTML=`<h3>${R.types[u.type].icon} ${R.types[u.type].name} #${u.id} · ${u.hp}/100 health</h3><div class="health"><span style="width:${u.hp}%"></span></div><p>Territory ${u.territory+1}${u.retreat?.turn===state.turn?' · <strong class="retreat">Retreated: moving away risks pursuit damage this turn</strong>':''}</p><div class="row"><label>Destination <select class="destination">${options(destinations.map(t=>[t.id,`${t.id+1} · ${t.name} (${R.route(state,u.territory,t.id,u.country).length} moves)`]),u.order?.destination??u.territory)}</select></label><label>Plan <select class="intent"><option value="move">Move / hold</option><option value="capture">Capture land</option></select></label><button>Save order</button></div><p>${u.order?`Saved: ${u.order.intent} at territory ${(u.order.destination??u.territory)+1}`:'No order: holds position.'}</p>`;box.querySelector('.intent').value=u.order?.intent||'move';box.querySelector('button').onclick=()=>change(s=>R.order(s,u.id,Number(box.querySelector('.destination').value),box.querySelector('.intent').value),'Order saved. It will resolve with everyone else.');panel.append(box);});
  if(!living().some(u=>u.country===active))panel.append(Object.assign(document.createElement('p'),{textContent:'No living regiments. Recruit in controlled territory. If you have lost all land, the teacher can start a new campaign or restore a previous phase.'}));
 }else if(state.phase==='decisions'){
  const diplomacy=document.createElement('div');diplomacy.innerHTML=`<h3>Alliances need both countries to agree</h3><p>Allies: ${esc(state.countries.filter(c=>c.id!==active&&R.ally(state,c.id,active)).map(c=>c.name).join(', ')||'None')}</p><div class="row"><select id="partner" aria-label="Alliance partner">${options(state.countries.filter(c=>c.id!==active).map(c=>[c.id,c.name]),'')}</select><button id="offer">Offer alliance</button></div>`;panel.append(diplomacy);$('offer').onclick=()=>change(s=>R.offer(s,active,Number($('partner').value)),'Offer sent. Switch to the other country to accept.');state.offers.filter(o=>o.to===active).forEach(o=>{const b=document.createElement('button');b.textContent=`Accept ${country(o.from)}’s offer`;b.onclick=()=>change(s=>R.accept(s,o.from,active),'Alliance agreed. Countries must reconfirm targets.');panel.append(b);});
  state.conflicts.filter(c=>c.countries.includes(active)).forEach(c=>{const box=document.createElement('article');box.className='conflict';box.innerHTML=`<h3>Territory ${c.territory+1} · ${esc(state.territories[c.territory].name)}</h3><p>Present: ${esc(c.countries.map(id=>country(id)+': '+living().filter(u=>u.territory===c.territory&&u.country===id).map(u=>R.types[u.type].name+' '+u.hp).join(', ')).join(' · '))}</p><button class="showSite">Show territory on map</button><label>Country to attack <select>${options([['unset','Choose…'],['hold','Hold / do not attack'],...c.countries.filter(id=>id!==active).map(id=>[id,country(id)+(R.ally(state,id,active)?' (ally—attack breaks agreement)':'')])],Object.hasOwn(state.choices,`${c.territory}:${active}`)?state.choices[`${c.territory}:${active}`]??'hold':'unset')}</select></label>`;box.querySelector('.showSite').onclick=()=>focusTerritory(c.territory);box.querySelector('select').onchange=e=>{if(e.target.value!=='unset')change(s=>R.target(s,active,c.territory,e.target.value==='hold'?null:Number(e.target.value)),'Target saved.');};panel.append(box);});const b=document.createElement('button');b.className='primary';b.textContent=state.ready.includes(active)?'Choices confirmed':'Confirm this country’s choices';b.disabled=state.ready.includes(active);b.onclick=()=>change(s=>R.confirm(s,active),'Country confirmed. Review the other countries.');panel.append(b);const req=[...new Set(state.conflicts.flatMap(c=>c.countries))];panel.append(Object.assign(document.createElement('p'),{textContent:`Waiting for: ${req.filter(id=>!state.ready.includes(id)).map(country).join(', ')||'Nobody — teacher can resolve.'}`}));
 }else if(state.phase==='retreat'){
 const units=living().filter(u=>u.country===active&&u.retreat?.required);if(!units.length)panel.textContent='This country has no required retreats.';units.forEach(u=>{const safe=R.retreatOptions(state,u),box=document.createElement('article');box.className='regiment';box.innerHTML=`<h3>${R.types[u.type].name} #${u.id} · ${u.hp} health</h3>${safe.length?`<label>Retreat to <select>${options([['','Choose a neighbor'],...safe.map(id=>[id,`${id+1} · ${state.territories[id].name}`])],u.retreatTo??'')}</select></label>`:'<p>No safe neighboring territory. This regiment will surrender when the teacher finishes retreats.</p>'}`;if(safe.length)box.querySelector('select').onchange=e=>{if(e.target.value!=='')change(s=>R.retreat(s,u.id,Number(e.target.value)),'Retreat saved.');};panel.append(box);});
 }else panel.textContent='Read the results below. The teacher starts the next planning cycle when everyone is ready.';
}
function renderReport(){const host=$('report');host.replaceChildren();const history=state.phase==='results'?state.history:[{turn:state.turn,moves:state.moves,battles:state.battles,events:[],income:[]},...state.history];history.slice(0,5).forEach(log=>{if(!log.moves.length&&!log.battles.length&&!log.events.length)return;const box=document.createElement('article');box.className='event';box.innerHTML=`<h3>Turn ${log.turn}</h3>`;const p=text=>box.append(Object.assign(document.createElement('p'),{textContent:text}));log.moves.forEach(m=>p(`${country(m.country)} regiment #${m.unit}: territory ${m.from+1} → ${m.to+1}.`));log.battles.forEach(b=>{const focus=document.createElement('button');focus.textContent=`Zoom to battle site · ${b.territory+1}`;focus.onclick=()=>focusTerritory(b.territory);box.append(focus);p(`Battle in territory ${b.territory+1}. Strongest surviving force: ${b.leaders.map(country).join(', ')||'none'}. ${b.losers.length?'Retreat: '+b.losers.map(country).join(', '):'No weaker damaged force must retreat.'}`);b.records.forEach(r=>p(`${country(r.country)} · ${R.types[r.type].name} #${r.id}: ${r.before} entered, ${r.lost} lost, ${r.remaining} health remains.`));});log.events.forEach(p);log.income?.forEach(i=>{if(i.country===active)p(`Your income: ${R.goods.map(g=>`${i[g]} ${g}`).join(', ')}.`);});host.append(box);});if(!host.childNodes.length)host.textContent='Movement and battle results appear after the teacher advances.';}
const ctx=$('map').getContext('2d');function polygon(c){ctx.beginPath();c.polygon.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();}
function draw(){ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#466eab';ctx.fillRect(0,0,1200,700);ctx.scale(1200/camera.w,700/camera.h);ctx.translate(-camera.x,-camera.y);const z=camera.w/1200;const edges=new Map();state.cells.filter(c=>c.land).forEach(c=>{const t=state.territories[c.territory];polygon(c);ctx.fillStyle=$('layer').value==='biome'?c.biome.color:state.countries[t.owner]?.color||'#d5dbb7';ctx.fill();if(t.id===selected){ctx.fillStyle='#fff6aa55';ctx.fill();}for(let i=0;i<c.polygon.length-1;i++){const k=[c.polygon[i],c.polygon[i+1]].map(p=>p.map(v=>v.toFixed(3)).join(',')).sort().join('|');if(edges.has(k)){const e=edges.get(k);if(e.territory===t.id)edges.delete(k);else e.border=true;}else edges.set(k,{from:c.polygon[i],to:c.polygon[i+1],territory:t.id});}});ctx.strokeStyle='#263e37';ctx.lineWidth=1.5*z;edges.forEach(e=>{ctx.beginPath();ctx.moveTo(...e.from);ctx.lineTo(...e.to);ctx.stroke();});state.territories.forEach(t=>{ctx.font=`bold ${11*z}px sans-serif`;ctx.textAlign='center';ctx.strokeStyle='#fff9e9';ctx.lineWidth=3*z;ctx.strokeText(t.id+1,...t.point);ctx.fillStyle='#203c35';ctx.fillText(t.id+1,...t.point);});
 state.moves.forEach(m=>{const a=state.territories[m.from].point,b=state.territories[m.to].point;if(m.from===m.to)return;ctx.strokeStyle=state.countries[m.country].color;ctx.lineWidth=4*z;ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke();const angle=Math.atan2(b[1]-a[1],b[0]-a[0]);ctx.beginPath();ctx.moveTo(...b);ctx.lineTo(b[0]-12*z*Math.cos(angle-.5),b[1]-12*z*Math.sin(angle-.5));ctx.moveTo(...b);ctx.lineTo(b[0]-12*z*Math.cos(angle+.5),b[1]-12*z*Math.sin(angle+.5));ctx.stroke();});
 const grouped=new Map();living().forEach(u=>{const n=grouped.get(u.territory)||0;grouped.set(u.territory,n+1);const t=state.territories[u.territory],x=t.point[0]+((n%4)-1)*28*z,y=t.point[1]+(18+Math.floor(n/4)*28)*z;ctx.fillStyle=state.countries[u.country].color;ctx.fillRect(x-12*z,y-12*z,25*z,25*z);ctx.strokeStyle=u.country===active?'#fff':'#233c35';ctx.lineWidth=2*z;ctx.strokeRect(x-12*z,y-12*z,25*z,25*z);ctx.font=`bold ${11*z}px sans-serif`;ctx.textAlign='center';ctx.fillStyle='#111';ctx.fillText(`${R.types[u.type].icon}${u.hp}`,x,y+4*z);if(u.retreat?.turn===state.turn){ctx.fillStyle='#b93724';ctx.fillText('↩',x,y-13*z);}});state.countries.filter(c=>c.shield).forEach(c=>{const t=state.territories[c.capital];if(!t)return;let img=shields.get(c.shield);if(!img){img=new Image();img.onload=draw;img.src=c.shield;shields.set(c.shield,img);}if(img.complete&&img.naturalWidth)ctx.drawImage(img,t.point[0]-12*z,t.point[1]-43*z,24*z,28*z);});ctx.setTransform(1,0,0,1,0,0);}
function contains(p,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
$('map').onclick=e=>{const b=$('map').getBoundingClientRect(),p=[camera.x+(e.clientX-b.left)/b.width*camera.w,camera.y+(e.clientY-b.top)/b.height*camera.h],c=state.cells.find(c=>c.land&&contains(p,c.polygon));if(c){selected=c.territory;render();}};
$('country').onchange=e=>{active=Number(e.target.value);selected=state.countries[active].capital??0;render();};$('territory').onchange=e=>{selected=Number(e.target.value);render();};$('layer').onchange=render;
function focusTerritory(id){selected=id;render();zoom(.5);$('map').scrollIntoView({block:'center',behavior:'smooth'});}
function zoom(f){const point=state.territories[selected].point,w=Math.max(250,Math.min(1200,camera.w*f)),h=w*700/1200;camera={x:Math.max(0,Math.min(1200-w,point[0]-w/2)),y:Math.max(0,Math.min(700-h,point[1]-h/2)),w,h};draw();}$('zoomIn').onclick=()=>zoom(.7);$('zoomOut').onclick=()=>zoom(1.4);$('fit').onclick=()=>{camera={x:0,y:0,w:1200,h:700};draw();};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
$('recover').onclick=()=>download(new Blob([unreadableSave],{type:'application/json'}),'unreadable-regiment-save.json');
$('save').onclick=()=>download(new Blob([JSON.stringify(state)],{type:'application/json'}),`regiment-game-turn-${state.turn}.json`);$('mapDownload').onclick=()=>$('map').toBlob(blob=>download(blob,`turn-${state.turn}-${state.phase}.png`));
$('advance').onclick=()=>ask('Advance all countries together? Unissued movement orders hold. Missing conflict choices or retreats will stop the advance.',()=>{try{const next=R.advance(state);localStorage.setItem(KEY+'-previous',JSON.stringify(state));state=next;save();render();notice('Phase resolved. Review the map and results.');}catch(e){notice(e.message);}});
$('undo').onclick=()=>ask('Restore the previous phase? Download the current game first if you want to keep it.',()=>{try{const raw=localStorage.getItem(KEY+'-previous');if(!raw)throw Error('No previous phase checkpoint yet.');const previous=R.validate(JSON.parse(raw));localStorage.setItem(KEY+'-previous',JSON.stringify(state));state=previous;active=0;selected=0;save();render();notice('Previous phase restored.');}catch(e){notice(e.message);}});
$('new').onclick=()=>ask('Start a fresh regiment game? The current game will be retained as the previous phase checkpoint.',()=>{try{const next=fresh();localStorage.setItem(KEY+'-previous',JSON.stringify(state));state=next;unreadableSave=null;$('recover').hidden=true;active=0;selected=0;save();render();}catch(e){notice(e.message);}});
async function load(e,importing){const file=e.target.files[0];if(!file)return;try{if(file.size>35e6)throw Error('Choose a file smaller than 35 MB.');const raw=JSON.parse(await file.text()),next=R.validate(importing?R.create(importAzgaarWorld(raw)):raw);ask('Replace the current regiment game? A previous-phase checkpoint will be kept.',()=>{try{localStorage.setItem(KEY+'-previous',JSON.stringify(state));state=next;unreadableSave=null;$('recover').hidden=true;active=0;selected=0;save();render();notice('Game opened.');}catch(error){notice(error.message);}});}catch(error){notice(error.message);}e.target.value='';}
$('import').onchange=e=>load(e,true);$('open').onchange=e=>load(e,false);
$('shield').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>5e6)return notice('Choose a shield smaller than 5 MB.');const reader=new FileReader(),id=active;reader.onload=()=>{const image=new Image();image.onload=()=>{const c=document.createElement('canvas');c.width=96;c.height=96;const x=c.getContext('2d'),scale=Math.min(96/image.width,96/image.height);x.drawImage(image,(96-image.width*scale)/2,(96-image.height*scale)/2,image.width*scale,image.height*scale);change(s=>s.countries[id].shield=c.toDataURL('image/png'),'Shield saved.');};image.src=reader.result;};reader.readAsDataURL(f);};
selected=state.countries[active].capital??0;render();
